"""Russian study, project and technology scenarios for the local chat corpus."""


def _scenes(topic, objects, patterns):
    items = [item.strip() for item in objects.split('|') if item.strip()]
    return tuple(
        (topic, prompt.format(item), replies[(index + pattern_index) % len(replies)])
        for pattern_index, (prompt, replies) in enumerate(patterns)
        for index, item in enumerate(items)
    )


